mapper.select:
select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

select * from FIN_PRODUCT
where FINPROD_MARKET_ID=#{finprodMarketId,jdbcType=VARCHAR}
    AND TRADE_MARKET in (#{TRADE_PLACE_01},#{TRADE_PLACE_02})
    AND FINPROD_TYPE2=#{finprodType2,jdbcType=VARCHAR}

SELECT SECFULLNAME,SECNAME,MARKET2,INSTITUTION,VDATE,MDATE,ISSUERSHORT,COUPONSPECIES,INTERESTRATE,CCY,MAX(SOURCE) SOURCE
from INTERF_PAYHSRCSECINFO WHERE SECID = #{finprodMarketId,jdbcType=VARCHAR}
group by SECFULLNAME,SECNAME,MARKET2,INSTITUTION,VDATE,MDATE,ISSUERSHORT,COUPONSPECIES,INTERESTRATE,CCY

SELECT SECID,SECFULLNAME,SECNAME,MARKET2,INSTITUTION,VDATE,MDATE,ISSUERSHORT,COUPONSPECIES,INTERESTRATE,CCY,SOURCE
from INTERF_PAYHSRCSECINFO
WHERE SECFULLNAME=#{finprodName,jdbcType=VARCHAR}
  and SECNAME=#{finprodAbbr,jdbcType=VARCHAR}
  and MARKET2=#{tradeMarket,jdbcType=VARCHAR}
  and INSTITUTION=#{registOrg,jdbcType=VARCHAR}
  and VDATE=#{vdate,jdbcType=DATE}
  and MDATE=#{mdate,jdbcType=DATE}
  and ISSUERSHORT=#{issuer,jdbcType=VARCHAR}
  and COUPONSPECIES=#{couponSpecies,jdbcType=VARCHAR}
  and INTERESTRATE=#{intType,jdbcType=VARCHAR}
  and CCY=#{ccy,jdbcType=VARCHAR}
